// Monta e ASSINA a requisicao do conversionReport da Shopee Affiliate API.
// Credenciais via variaveis de ambiente do n8n (NUNCA no fluxo):
//   SHOPEE_APP_ID, SHOPEE_SECRET
// Assinatura oficial: SHA256(AppId + Timestamp + Payload + Secret) em hex.
const APP_ID = $env.SHOPEE_APP_ID;
const SECRET = $env.SHOPEE_SECRET;
if (!APP_ID || !SECRET) throw new Error('Defina SHOPEE_APP_ID e SHOPEE_SECRET nas variaveis do n8n');

const fim = Math.floor(Date.now() / 1000);
const ini = fim - 7 * 24 * 3600; // ultimos 7 dias (reprocessa por seguranca; ingest e idempotente)

const query = `query { conversionReport(purchaseTimeStart: ${ini}, purchaseTimeEnd: ${fim}, limit: 500) { nodes { conversionId orderId purchaseTime totalCommission netCommission utmContent campaignType } pageInfo { scrollId hasNextPage } } }`;
const payload = JSON.stringify({ query });
const ts = Math.floor(Date.now() / 1000);

const base = `${APP_ID}${ts}${payload}${SECRET}`;
const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(base));
const sig = [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, '0')).join('');

return [{ json: {
  endpoint: 'https://open-api.affiliate.shopee.com.br/graphql',
  authorization: `SHA256 Credential=${APP_ID}, Timestamp=${ts}, Signature=${sig}`,
  payload
} }];

// Extrai as conversoes e mapeia pro contrato do Worker (/conversion).
// O utmContent traz o click_id que o /go injetou como sub_id -> junção exata.
const data = $json.data && $json.data.conversionReport;
if (!data || !Array.isArray(data.nodes)) return [];
return data.nodes.map(n => ({ json: {
  conversion_id: n.conversionId,
  order_id: n.orderId,
  click_id: n.utmContent,
  purchase_time: Number(n.purchaseTime) || null,
  total_commission: Number(n.totalCommission) || 0,
  net_commission: Number(n.netCommission) || 0,
  campaign_type: n.campaignType || null
} }));
